void IncomingKey(lv_event_t * e)
{
    // Your code here
    uint32_t key = lv_event_get_key(e);
    lv_indev_wait_release(lv_indev_get_act());
    switch (key)
    {
    case LV_KEY_HOME:
    case LV_KEY_ENTER:
    case LV_KEY_GREEN:
        call_flow_anwser();
        LV_LOG_USER("[key test] incoming LV_KEY_GREEN");
        break;
    case LV_KEY_BACKSPACE:
    case LV_KEY_END:
        LV_LOG_USER("[key test] incoming key=%d",key);
        LV_LOG_USER("[key test] reject incoming ");
        call_flow_reject();
        break;
    default:
        LV_LOG_USER("[key test] incoming other keys");
        break;
    }
}

